/**
 * Re-express one lot after a simple share split, preserving total basis.
 *
 * A split changes the share count and the per-share basis together.  The
 * check that matters is that the product does not move: pairing the new
 * quantity with the pre-split per-share basis is the classic way to double a
 * cost basis that never changed.
 */
export function applySplitToLot(shares: unknown, basisPerShare: unknown, splitRatio: unknown): SplitCheck {
  const quantity = asReal(shares, "shares");
  const basis = asReal(basisPerShare, "basisPerShare");
  const ratio = asReal(splitRatio, "splitRatio");
  if (quantity < 0) invalid("invalid-lot-shares", "shares must be nonnegative.");
  if (basis < 0) invalid("invalid-basis", "basisPerShare must be nonnegative.");
  if (ratio <= 0) invalid("invalid-split-ratio", "splitRatio must be positive; it is new shares per old share.");

  const sharesAfter = quantity * ratio;
  const basisAfter = basis / ratio;
  const totalBefore = quantity * basis;
  const totalAfter = sharesAfter * basisAfter;
  const stale = sharesAfter * basis;
  const scale = Math.max(1, Math.abs(totalBefore));
  return {
    splitRatio: ratio,
    sharesBefore: quantity, basisPerShareBefore: basis, totalBasisBefore: totalBefore,
    sharesAfter, basisPerShareAfter: basisAfter, totalBasisAfter: totalAfter,
    totalBasisPreserved: Math.abs(totalAfter - totalBefore) <= RELATIVE_TOLERANCE * scale,
    // What the ledger would say if the new quantity kept the old per-share
    // basis.  It is the error this check exists to catch, never a basis.
    stalePairingTotalBasis: stale,
    stalePairingOverstatement: stale - totalBefore,
  };
}

function normalizeLot(entry: unknown, index: number, price: number, tradeOrdinal: number, label: string): LotRecord {
  const name = `${label}[${index}]`;
  if (!isPlainRecord(entry)) invalid("invalid-lot", `${name} must be an object describing one acquisition lot.`);
  const unknown = Object.keys(entry).filter((key) => !LOT_FIELDS.includes(key)).sort();
  if (unknown.length) {
    invalid(
      "unknown-lot-field",
      `${name} has unrecognized fields ${JSON.stringify(unknown)}; the coefficient field is 'illustrativeRate' `
      + "because it is a declared teaching weight, not a tax rate this package can look up.",
    );
  }
  const lotId = text(entry.lotId, `${name}.lotId`, "invalid-lot");
  const shares = asReal(entry.shares, `${name}.shares`);
  if (shares < 0) invalid("invalid-lot-shares", `${name}.shares must be nonnegative.`);
  const [acquiredOn, acquiredOrdinal] = isoDate(entry.acquiredOn, `${name}.acquiredOn`);
  if (acquiredOrdinal > tradeOrdinal) {
    invalid(
      "lot-acquired-after-trade-date",
      `${name} was acquired after the trade date; a later acquisition cannot inform today's decision.`,
    );
  }

  const declared = entry.saleScoreRate;
  const rawBasis = entry.basisPerShare;
  const rawRate = entry.illustrativeRate;
  let basisPerShare: number | null = null;
  let illustrativeRate: number | null = null;
  let perDollarScore: number;
  if (declared !== undefined && declared !== null) {
    if ((rawBasis !== undefined && rawBasis !== null) || (rawRate !== undefined && rawRate !== null)) {
      invalid(
        "ambiguous-lot-score",
        `${name} declares saleScoreRate as well as basis/coefficient inputs; supply one form only.`,
      );
    }
    perDollarScore = asReal(declared, `${name}.saleScoreRate`);
  } else {
    if (rawBasis === undefined || rawBasis === null) {
      invalid(
        "missing-basis",
        `${name}.basisPerShare is missing; assuming zero basis is not a safe missing-data policy.`,
      );
    }
    if (rawRate === undefined || rawRate === null) {
      invalid(
        "missing-coefficient",
        `${name}.illustrativeRate is missing; the coefficient is declared by the caller and is never inferred `
        + "from a ticker, an acquisition date, or a reader's location.",
      );
    }
    basisPerShare = asReal(rawBasis, `${name}.basisPerShare`);
    illustrativeRate = asReal(rawRate, `${name}.illustrativeRate`);
    if (basisPerShare < 0) invalid("invalid-basis", `${name}.basisPerShare must be nonnegative.`);
    if (illustrativeRate < 0) invalid("invalid-coefficient", `${name}.illustrativeRate must be nonnegative.`);
    perDollarScore = illustrativeRate * (1 - basisPerShare / price);
  }
  return {
    lotId, acquiredOn, acquiredOrdinal, declaredIndex: index, sharesAvailable: shares,
    basisPerShare, illustrativeRate, perDollarScore, capacity: shares * price,
  };
}

function normalizeLots(lots: unknown, price: number, tradeOrdinal: number, label: string): LotRecord[] {
  if (!Array.isArray(lots)) invalid("invalid-input", `${label} must be an ordered array of lot records.`);
  if (lots.length === 0) invalid("invalid-input", `${label} must contain at least one lot.`);
  const records = lots.map((entry, index) => normalizeLot(entry, index, price, tradeOrdinal, label));
  const seen = new Set<string>();
  for (const record of records) {
    if (seen.has(record.lotId)) invalid("duplicate-lot-id", `${label} repeats lot id "${record.lotId}".`);
    seen.add(record.lotId);
  }
  return records;
}

function fillRank(record: LotRecord, fillOrder: FillOrder): [number, number, number] {
  // Ascending per-dollar score minimizes the declared separable score for a
  // sale whose size is already fixed.  Age and declared order only break
  // ties, so the ranking stays reproducible.
  return fillOrder === "lowest-score"
    ? [record.perDollarScore, record.acquiredOrdinal, record.declaredIndex]
    : [record.acquiredOrdinal, record.declaredIndex, record.declaredIndex];
}

function fillLots(
  records: readonly LotRecord[], saleDollars: number, fillOrder: FillOrder, price: number,
): { fills: LotFill[]; sequence: string[]; totalCapacity: number; totalScore: number } {
  const totalCapacity = stableSum(records.map((record) => record.capacity));
  if (saleDollars > totalCapacity + CAPACITY_TOLERANCE * Math.max(1, totalCapacity)) {
    invalid(
      "sale-exceeds-capacity",
      `a ${saleDollars} dollar sale exceeds the ${totalCapacity} dollars of validated lot capacity; `
      + "lot ordering cannot create additional shares.",
    );
  }
  const filled = records.map(() => 0);
  const sequence: string[] = [];
  let remaining = saleDollars;
  const ordered = [...records].sort((left, right) => {
    const a = fillRank(left, fillOrder);
    const b = fillRank(right, fillOrder);
    return (a[0] - b[0]) || (a[1] - b[1]) || (a[2] - b[2]);
  });
  for (const record of ordered) {
    if (remaining <= 0) break;
    const take = Math.min(remaining, record.capacity);
    if (take <= 0) continue;
    filled[record.declaredIndex] = take;
    remaining -= take;
    sequence.push(record.lotId);
  }
  if (remaining > CAPACITY_TOLERANCE * Math.max(1, totalCapacity)) {
    throw new TaxAwareNumericalError(
      "fill-residual", "the requested sale could not be filled from the validated lot capacity.",
    );
  }
  const fills: LotFill[] = records.map((record) => {
    const sale = filled[record.declaredIndex];
    return {
      lotId: record.lotId,
      acquiredOn: record.acquiredOn,
      sharesAvailable: record.sharesAvailable,
      basisPerShare: record.basisPerShare,
      illustrativeRate: record.illustrativeRate,
      perDollarScore: record.perDollarScore,
      capacity: record.capacity,
      saleDollars: sale,
      sharesSold: sale / price,
      remainingCapacity: record.capacity - sale,
      // T_ij * s_ij for this lot: a modeled score, not a tax bill.
      lotScore: record.perDollarScore * sale,
    };
  });
  return { fills, sequence, totalCapacity, totalScore: stableSum(fills.map((fill) => fill.lotScore)) };
}

/**
 * Score a sale whose dollar size is already fixed against its lots.
 *
 * Each lot contributes `T_ij * s_ij` with `T_ij = rho_ij (1 - b_ij/p_i)` and
 * `0 <= s_ij <= q_ij p_i`, and the fills sum to the requested sale.
 * `fillOrder` chooses between the ascending-score fill, which minimizes the
 * declared score for this fixed sale size, and the oldest-first fill, which
 * is here only so the two can be compared.
 *
 * The answer is a ranking under the supplied coefficients.  It does not
 * establish that the taxpayer may identify those shares, and the returned
 * score is never cash: `settlementCash` is zero in both directions.
 */
export function scoreFixedSale(
  assetId: unknown, price: unknown, lots: unknown, saleDollars: unknown, tradeDate: unknown,
  options: { fillOrder?: FillOrder; policy?: unknown } = {},
): FixedSaleResult {
  const asset = text(assetId, "assetId");
  const mark = asReal(price, "price");
  if (mark <= 0) invalid("invalid-price", "price must be positive; the score divides the basis by the mark.");
  const fillOrder = options.fillOrder ?? "lowest-score";
  if (!FILL_ORDERS.includes(fillOrder)) {
    invalid("unknown-fill-order", `fillOrder must be one of ${JSON.stringify(FILL_ORDERS)}.`);
  }
  const [tradeDay, tradeOrdinal] = isoDate(tradeDate, "tradeDate");
  const records = normalizeLots(lots, mark, tradeOrdinal, "lots");
  const sale = asReal(saleDollars, "saleDollars");
  if (sale < 0) invalid("invalid-sale-amount", "saleDollars must be nonnegative.");

  const { fills, sequence, totalCapacity, totalScore } = fillLots(records, sale, fillOrder, mark);
  return {
    assetId: asset,
    tradeDate: tradeDay,
    price: mark,
    fillOrder,
    saleDollars: sale,
    sharesSold: stableSum(fills.map((fill) => fill.sharesSold)),
    totalCapacity,
    remainingCapacity: stableSum(fills.map((fill) => fill.remainingCapacity)),
    totalScore,
    fillSequence: sequence,
    lots: fills,
    // A score is an objective input.  Negative or positive, it moves no money
    // here; only a declared settlement does, via settleTradeCash.
    settlementCash: 0,
    scoreIsObjectiveOnly: true,
    policy: reviewPolicyState(options.policy),
    certificate: {
      kind: "separable-lot-score-fill",
      fillOrder,
      minimizesDeclaredScore: fillOrder === "lowest-score",
      scope: "one asset, one currency, one period, no cross-lot or cross-account coupling",
      note:
        "ascending per-dollar score minimizes the declared separable score for a fixed sale size; "
        + "that is a modeling result under the supplied coefficients, not a statutory lot-ordering rule",
    },
  };
}

/**
 * Reconcile the cash ledger, charging any declared tax amount once.
 *
 * A score in the objective is not money leaving the account on trade day.
 * Under `objective-only-forecast` the immediate `taxCash` is zero by
 * construction.  Only a caller-declared settlement moves cash, through
 * `cashPost = cashInit - sum(trade) - executionCost - taxCash`, and
 * `portfolioValuePost` then adds that already-net balance instead of
 * subtracting the same amount a second time.
 */
export function settleTradeCash(
  cashInit: unknown, trade: unknown, executionCost: unknown,
  options: {
    taxCash?: unknown; settlement?: SettlementMode; settlementDate?: unknown; holdingsPost?: unknown;
  } = {},
): CashLedger {
  const settlement = options.settlement ?? "objective-only-forecast";
  if (!SETTLEMENT_MODES.includes(settlement)) {
    invalid("unknown-settlement-mode", `settlement must be one of ${JSON.stringify(SETTLEMENT_MODES)}.`);
  }
  const opening = asReal(cashInit, "cashInit");
  const signed = vector(trade, "trade");
  const cost = asReal(executionCost, "executionCost");
  if (cost < 0) invalid("negative-execution-cost", "executionCost must be nonnegative.");
  const settled = asReal(options.taxCash ?? 0, "taxCash");
  let settlementDay: string | null = null;
  if (settlement === "objective-only-forecast") {
    if (settled !== 0) {
      invalid(
        "tax-cash-without-settlement-policy",
        "taxCash must be zero while the model only forecasts; declare settlement='settles-at-trade' with its "
        + "timing before any amount moves.",
      );
    }
  } else {
    if (settled < 0) {
      invalid(
        "negative-tax-cash",
        "taxCash must be nonnegative; a negative modeled loss score is not a refund and must not increase cash.",
      );
    }
    if (options.settlementDate === undefined || options.settlementDate === null) {
      invalid(
        "settlement-date-required",
        "settlement='settles-at-trade' requires the date on which the declared amount settles.",
      );
    }
    settlementDay = isoDate(options.settlementDate, "settlementDate")[0];
  }

  const tradeTotal = stableSum(signed);
  const cashPost = stableSum([opening, -tradeTotal, -cost, -settled]);
  const holdingsTotalPost = options.holdingsPost === undefined || options.holdingsPost === null
    ? null : stableSum(vector(options.holdingsPost, "holdingsPost"));
  return {
    settlement,
    settlementDate: settlementDay,
    cashInit: opening,
    tradeTotal,
    executionCost: cost,
    taxCash: settled,
    cashPost,
    holdingsTotalPost,
    portfolioValuePost: holdingsTotalPost === null ? null : holdingsTotalPost + cashPost,
    taxChargedTo: settlement === "settles-at-trade" ? "cash-settlement" : "objective-score-only",
    note:
      "taxCash is subtracted once, inside cashPost; portfolioValuePost adds that net balance and never "
      + "subtracts the same amount again from terminal wealth",
  };
}

/**
 * Maximize `curvature*x^2 + slope*x + constant` on `[lower, upper]`.
 *
 * `curvature` is `-gammaRisk * dᵀVd` and is never positive for a
 * positive-semidefinite risk matrix, so the branch is concave and the
 * stationary point plus the two endpoints exhaust the candidates.
 */
function maximizeBranch(
  label: BranchRecord["branch"], curvature: number, slope: number, constant: number,
  lower: number, upper: number,
): BranchRecord {
  const value = (x: number) => curvature * x * x + slope * x + constant;
  const stationary = curvature < 0 ? slope / (-2 * curvature) : null;
  const feasible = stationary !== null && stationary >= lower && stationary <= upper;
  const candidates = feasible ? [lower, upper, stationary as number] : [lower, upper];
  let bestX = candidates[0];
  let bestValue = value(bestX);
  for (const candidate of candidates.slice(1)) {
    const candidateValue = value(candidate);
    const tolerance = RELATIVE_TOLERANCE * Math.max(Math.abs(candidateValue), Math.abs(bestValue));
    if (candidateValue > bestValue + tolerance) {
      bestX = candidate; bestValue = candidateValue;
    } else if (candidateValue >= bestValue - tolerance && Math.abs(candidate) < Math.abs(bestX)) {
      // A tie inside the comparison tolerance resolves to the smaller trade,
      // so a flat branch reports no trade rather than a boundary.
      bestX = candidate; bestValue = candidateValue;
    }
  }
  const binding = feasible && bestX === stationary ? "stationary" : bestX === lower ? "lower-bound" : "upper-bound";
  return {
    branch: label,
    interval: [lower, upper],
    quadraticCoefficient: curvature,
    linearCoefficient: slope,
    constant,
    stationaryX: stationary,
    stationaryInInterval: feasible,
    x: bestX,
    binding,
    utility: bestValue,
  };
}

/**
 * Maximize the teaching utility exactly, inside a narrow declared scope.
 *
 * The utility is `U(h,u) = aᵀu - gammaRisk (h-h_b)ᵀV(h-h_b) - gammaTc C(u)
 * - gammaTax L_policy(u)` with `h = h_init + u` and `C(u) = kappaᵀ|u|`.
 *
 * Declared scope: exactly `ORACLE_ASSETS` assets, exactly
 * `ORACLE_LOTS_PER_ASSET` lot per asset, and a cash-neutral trade, so
 * `sum(u) = 0` and `u = [x, -x]` with `x` bounded by the sale capacity on
 * each side.  Inside that scope the problem collapses to one free variable,
 * each sign branch fixes the buy/sell direction and is a concave quadratic in
 * `x`, and both branches are maximized in closed form: the result is the
 * exact global optimum of this restricted toy problem and nothing wider.  A
 * second lot per asset would make the score piecewise linear and make the
 * answer depend on the fill order, which is a different problem than the one
 * the article solves, so it is rejected rather than approximated.
 */
export function optimizeTaxAwareTrade(
  holdingsInit: unknown, benchmark: unknown, expectedReturn: unknown, riskMatrix: unknown,
  prices: unknown, lots: unknown, tradeDate: unknown,
  options: {
    gammaRisk?: unknown; gammaTax?: unknown; gammaTc?: unknown; costRates?: unknown;
    cashInit?: unknown; taxCash?: unknown; settlement?: SettlementMode; settlementDate?: unknown;
    policy?: unknown;
  } = {},
): TradeResult {
  const holdings = vector(holdingsInit, "holdingsInit");
  const size = holdings.length;
  if (size !== ORACLE_ASSETS) {
    invalid(
      "scope-limit",
      `the exact oracle is declared for exactly ${ORACLE_ASSETS} assets under a cash-neutral trade; a wider `
      + "problem needs a certified convex solver per fixed direction.",
    );
  }
  const target = vector(benchmark, "benchmark");
  const mean = vector(expectedReturn, "expectedReturn");
  const risk = matrix(riskMatrix, "riskMatrix", size);
  const mark = vector(prices, "prices");
  if (target.length !== size || mean.length !== size || mark.length !== size) {
    invalid("invalid-input", "holdingsInit, benchmark, expectedReturn, and prices must align.");
  }
  if (holdings.some((value) => value < 0)) invalid("invalid-input", "holdingsInit must be nonnegative dollar holdings.");
  if (mark.some((value) => value <= 0)) invalid("invalid-price", "every price must be positive.");
  const riskWeight = asReal(options.gammaRisk ?? 1, "gammaRisk");
  const taxWeight = asReal(options.gammaTax ?? 1, "gammaTax");
  const costWeight = asReal(options.gammaTc ?? 0, "gammaTc");
  for (const [name, value] of [["gammaRisk", riskWeight], ["gammaTax", taxWeight], ["gammaTc", costWeight]] as const) {
    if (value < 0) invalid("invalid-coefficient", `${name} must be nonnegative.`);
  }
  const kappa = options.costRates === undefined || options.costRates === null
    ? holdings.map(() => 0) : vector(options.costRates, "costRates");
  if (kappa.length !== size) invalid("invalid-input", "costRates must align with holdingsInit.");
  if (kappa.some((value) => value < 0)) {
    invalid("invalid-coefficient", "costRates must be nonnegative per-dollar execution rates.");
  }

  const scale = Math.max(...risk.flat().map((value) => Math.abs(value)));
  if (scale > 0) {
    if (Math.abs(risk[0][1] - risk[1][0]) > 1e-12 * scale) {
      invalid("indefinite-risk-matrix", "riskMatrix must be symmetric at the matrix scale.");
    }
    if (minimumSymmetricEigenvalue2x2(risk) < -PSD_RELATIVE_TOLERANCE * scale) {
      invalid("indefinite-risk-matrix", "riskMatrix must be positive semidefinite.");
    }
  }

  const [tradeDay, tradeOrdinal] = isoDate(tradeDate, "tradeDate");
  if (!Array.isArray(lots) || lots.length !== size) invalid("invalid-input", "lots must hold one lot list per asset.");
  const perAsset: LotRecord[][] = [];
  for (let index = 0; index < size; index += 1) {
    const records = normalizeLots(lots[index], mark[index], tradeOrdinal, `lots[${index}]`);
    if (records.length !== ORACLE_LOTS_PER_ASSET) {
      invalid(
        "scope-limit",
        `the exact oracle is declared for ${ORACLE_LOTS_PER_ASSET} lot per asset; lots[${index}] has `
        + `${records.length}, which would make the score piecewise linear and fill-order dependent.`,
      );
    }
    const capacity = stableSum(records.map((record) => record.capacity));
    if (capacity > holdings[index] + CAPACITY_TOLERANCE * Math.max(1, holdings[index])) {
      invalid(
        "lot-capacity-exceeds-holding",
        `lots[${index}] can sell ${capacity} dollars but the validated holding is ${holdings[index]}.`,
      );
    }
    perAsset.push(records);
  }

  const capacities = perAsset.map((records) => stableSum(records.map((record) => record.capacity)));
  const saleRates = perAsset.map((records) => records[0].perDollarScore);

  // u = [x, -x], so the whole objective is one quadratic in x per sign branch.
  const gap = holdings.map((value, index) => value - target[index]);
  const direction = [1, -1];
  const curvature = -riskWeight * quadraticForm(risk, direction, direction);
  const cross = quadraticForm(risk, gap, direction);
  const constant = -riskWeight * quadraticForm(risk, gap, gap);
  const returnSlope = mean[0] - mean[1];
  const riskSlope = -2 * riskWeight * cross;
  const costSlope = costWeight * (kappa[0] + kappa[1]);

  const branches: BranchRecord[] = [
    maximizeBranch(
      "buy-first-sell-second", curvature,
      returnSlope + riskSlope - taxWeight * saleRates[1] - costSlope, constant, 0, capacities[1],
    ),
    maximizeBranch(
      "sell-first-buy-second", curvature,
      returnSlope + riskSlope + taxWeight * saleRates[0] + costSlope, constant, -capacities[0], 0,
    ),
  ];
  let best = branches[0];
  const tolerance = RELATIVE_TOLERANCE * Math.max(Math.abs(branches[0].utility), Math.abs(branches[1].utility));
  if (branches[1].utility > best.utility + tolerance) best = branches[1];
  else if (branches[1].utility >= best.utility - tolerance && Math.abs(branches[1].x) < Math.abs(best.x)) best = branches[1];

  const x = best.x;
  const trade = [x, -x];
  const post = holdings.map((value, index) => value + trade[index]);
  const deviation = post.map((value, index) => value - target[index]);
  const executionCost = stableSum(kappa.map((rate, index) => rate * Math.abs(trade[index])));
  const sold = x > 0 ? 1 : x < 0 ? 0 : null;
  const saleDollars = Math.abs(x);
  const taxScore = sold === null ? 0 : saleRates[sold] * saleDollars;

  const expectedTerm = dot(mean, trade);
  const riskTerm = riskWeight * quadraticForm(risk, deviation, deviation);
  const costTerm = costWeight * executionCost;
  const taxTerm = taxWeight * taxScore;
  const utility = stableSum([expectedTerm, -riskTerm, -costTerm, -taxTerm]);
  if (Math.abs(utility - best.utility) > ABSOLUTE_TOLERANCE * Math.max(1, Math.abs(utility))) {
    throw new TaxAwareNumericalError(
      "objective-mismatch", "the branch polynomial and the direct utility disagree beyond tolerance.",
    );
  }

  let lotSales: TradeResult["lotSales"] = null;
  if (sold !== null) {
    const filled = fillLots(perAsset[sold], saleDollars, "lowest-score", mark[sold]);
    lotSales = {
      asset: sold, price: mark[sold], saleDollars, totalCapacity: filled.totalCapacity,
      fillSequence: filled.sequence, totalScore: filled.totalScore, lots: filled.fills,
    };
  }

  const cash = settleTradeCash(options.cashInit ?? 0, trade, executionCost, {
    taxCash: options.taxCash ?? 0,
    settlement: options.settlement ?? "objective-only-forecast",
    settlementDate: options.settlementDate,
    holdingsPost: post,
  });
  if (![...post, utility, executionCost, taxScore].every(Number.isFinite)) {
    throw new TaxAwareNumericalError("nonfinite-result", "the oracle returned a non-finite diagnostic.");
  }
  return {
    status: "optimal",
    tradeDate: tradeDay,
    trade,
    tradeTotal: stableSum(trade),
    holdings: post,
    direction: sold === null ? "no-trade" : best.branch,
    utility,
    terms: {
      expectedReturn: expectedTerm, riskPenalty: riskTerm,
      executionCostPenalty: costTerm, taxScorePenalty: taxTerm,
    },
    executionCost,
    // L_policy(u) in objective dollars under the declared coefficients.  It
    // is not a tax bill and it is not the cash in the ledger below.
    taxScore,
    saleCapacities: capacities,
    lotSales,
    branches,
    cash,
    policy: reviewPolicyState(options.policy),
    certificate: {
      kind: "direction-fixed-branch-enumeration",
      scope:
        `${ORACLE_ASSETS} assets, ${ORACLE_LOTS_PER_ASSET} declared lot each, cash-neutral sum(u)=0 so u=[x,-x]`,
      branchesChecked: branches.length,
      complete: true,
      globalOptimality:
        "each sign branch fixes the buy/sell direction, is concave in the single free variable x, and was "
        + "maximized in closed form over its closed interval; the better branch is the exact global optimum of "
        + "this restricted toy problem",
      taxModel: "declared illustrative lot score; no jurisdiction rule is applied",
    },
  };
}

/** The article's whole-portfolio oracle inputs. */
export function canonicalExample() {
  return {
    holdingsInit: [500, 500],
    benchmark: [600, 400],
    expectedReturn: [0.04, 0],
    riskMatrix: [[0.0001, 0], [0, 0.0001]],
    prices: [1, 1],
    lots: [
      [{ lotId: "A", shares: 500, saleScoreRate: 0.05, acquiredOn: "2025-01-02" }],
      [{ lotId: "B", shares: 500, saleScoreRate: 0.01, acquiredOn: "2025-01-02" }],
    ],
    tradeDate: "2026-01-02",
    options: { gammaRisk: 1, gammaTax: 1, gammaTc: 0 },
  };
}
